/**
 * One scenario per check of next-service-build-standard, for Install Book.
 *
 * Generated by `npx @aipathway/conformance init next-service-build-standard`,
 * then written for a small Australian plumbing and air conditioning business
 * that installs hot water systems, split systems and solar inverters.
 *
 * THE FIXTURES ARE ILLUSTRATIVE. The schedule months, makes and models below
 * exercise the build; they are not a statement of any maker's service
 * schedule or warranty. The business writes its own schedule from the maker's
 * instructions. Customers and numbers are made up.
 *
 * Every holds() reads the trace (world.calls), never the build's return value,
 * and returns a strict boolean. Each was run against a do-nothing build and
 * against deliberately broken builds before the committed run (see
 * broken-builds.mjs and README.md).
 */

import { ServiceBookWorld } from "./service-book-world.mjs";

// 10:00 in Brisbane on Thursday 5 November 2026.
const NOW = "2026-11-05T00:00:00.000Z";
const FIELDS = ["equipment_type", "make", "model", "serial", "installed_on", "serviced_on", "warranty_months"];
const TZ_DATE = (iso) =>
  new Intl.DateTimeFormat("en-CA", { timeZone: "Australia/Brisbane", year: "numeric", month: "2-digit", day: "2-digit" }).format(
    new Date(iso),
  );
const daysBetween = (a, b) => Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 86_400_000);

/* ---------------- fixtures ---------------- */

const SCHEDULE = { "hot water system": 12, "split system air conditioner": 12, "solar inverter": 12 };

const customer = (id, first_name, consent = { sms: true }) => ({
  id,
  first_name,
  mobile: `0491 570 ${String(100 + id.length * 7).slice(-3)}`,
  email: `${first_name.toLowerCase()}@example.com`,
  consent,
});

const equip = (over = {}) => ({
  equipment_type: "hot water system",
  make: "Rheem",
  model: "Stellar 315",
  serial: null,
  installed_on: "2025-11-20",
  serviced_on: null,
  warranty_months: null,
  ...over,
});

const job = (job_id, asset_id, customer_id, equipment, kind = "install", status = "complete", extra = {}) => ({
  job_id,
  kind,
  status,
  customer_id,
  asset_id,
  equipment,
  ...extra,
});

const world = (jobs, customers, schedule = SCHEDULE) =>
  Object.assign(new ServiceBookWorld({ now: NOW, jobs, customers, schedule }), { marks: [] });

/* ---------------- trace helpers ---------------- */

async function run(build, w) {
  w.marks.push(w.calls.length);
  await build(w.ports());
}

const callsOf = (w, n) =>
  n === undefined ? w.calls : w.calls.slice(w.marks[n] ?? 0, w.marks[n + 1] ?? w.calls.length);
const of = (w, port, n) => callsOf(w, n).filter((c) => c.port === port);
const attempts = (w, n) => of(w, "send_message", n);
const sent = (w, n) => attempts(w, n).filter((c) => c.response?.sent === true);
const raisedKind = (w, kind, ref) => of(w, "escalate").some((c) => c.request?.kind === kind && c.request?.ref === ref);
const writes = (w) => of(w, "write_job").filter((c) => c.response?.job_id);

const describe = (w) => {
  const s = attempts(w);
  const e = of(w, "escalate").map((c) => `${c.request?.kind}@${c.request?.ref}`);
  return `${w.calls.length} port call(s); ${s.length} send attempt(s) [${s
    .map((c) => `${c.request?.asset_id}/${c.request?.kind}/${c.request?.due_on}/${c.request?.stage}/${c.request?.channel}`)
    .join(", ")}]; escalations [${e.join(", ")}]; ${writes(w).length} booking write(s)`;
};

/* ---------------- scenarios ---------------- */

export const scenarios = [
  {
    checkId: "captured-at-completion",
    world: () =>
      world(
        [
          job("J101", "A-HWS-1", "C1", equip({ serial: "RH315-0099", installed_on: "2026-10-30", warranty_months: 60 })),
          job(
            "J102",
            "A-AC-1",
            "C2",
            equip({ equipment_type: "split system air conditioner", make: "Daikin", model: "FTXM35", installed_on: "2024-03-01", serviced_on: "2026-10-28" }),
            "service",
          ),
          job("J103", "A-HWS-2", "C3", equip({ installed_on: "2026-11-04" }), "install", "open"),
        ],
        [customer("C1", "Ana"), customer("C2", "Ben"), customer("C3", "Cleo")],
      ),
    drive: async (build, w) => {
      await run(build, w);
      await run(build, w);
    },
    holds: (w) => {
      const recs = of(w, "record_service").filter((c) => c.response?.record_id);
      const done = w.jobs.filter((j) => j.status === "complete");
      const eachOnce = done.every((j) => {
        const mine = recs.filter((c) => c.request?.source_job_id === j.job_id);
        return (
          mine.length === 1 &&
          mine[0].request.asset_id === j.asset_id &&
          FIELDS.every((f) => mine[0].request[f] === (j.equipment[f] ?? null))
        );
      });
      const openNone = !recs.some((c) => c.request?.source_job_id === "J103");
      return done.length === 2 && eachOnce && openNone;
    },
    describe: (w) =>
      `${describe(w)}; record_service: ${of(w, "record_service")
        .map((c) => c.request?.source_job_id)
        .join(", ")}`,
  },
  {
    checkId: "missing-details-to-a-person",
    world: () =>
      world(
        [
          job("J201", "A-NODATE", "C1", equip({ installed_on: null })),
          job("J202", "A-NOMODEL", "C2", equip({ model: null })),
          job("J203", "A-NOTYPE", "C3", equip({ equipment_type: null })),
          job("J204", "A-FILTER", "C4", equip({ equipment_type: "water filter", make: "Puretec", model: "Z1" })),
          job("J205", "A-GOOD", "C5", equip()),
        ],
        [customer("C1", "Ana"), customer("C2", "Ben"), customer("C3", "Cleo"), customer("C4", "Dev"), customer("C5", "Eve")],
      ),
    drive: (build, w) => run(build, w),
    holds: (w) => {
      const gaps = [
        ["A-NODATE", "missing_install_date"],
        ["A-NOMODEL", "missing_model"],
        ["A-NOTYPE", "missing_equipment_type"],
        ["A-FILTER", "no_schedule"],
      ];
      const raised = gaps.every(([a, k]) => raisedKind(w, k, a));
      const silent = gaps.every(([a]) => !attempts(w).some((c) => c.request?.asset_id === a));
      const goodSent = sent(w).filter((c) => c.request?.asset_id === "A-GOOD").length === 1;
      const goodClean = !of(w, "escalate").some((c) => c.request?.ref === "A-GOOD");
      return raised && silent && goodSent && goodClean;
    },
    describe,
  },
  {
    checkId: "dates-derived-not-stored",
    world: () =>
      world(
        [
          job("J301", "A-HWS-3", "C1", equip({ installed_on: "2024-05-14" })),
          job("J302", "A-HWS-3", "C1", equip({ installed_on: "2024-05-14", serviced_on: "2026-05-14" }), "service", "complete", {
            next_due_typed: "2026-11-10",
          }),
        ],
        [customer("C1", "Ana")],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.setSchedule("hot water system", 6);
      await run(build, w);
    },
    holds: (w) => {
      const before = attempts(w, 0).length === 0;
      const after = sent(w, 1);
      const right = after.length === 1 && after[0].request.kind === "service" && after[0].request.due_on === "2026-11-14";
      const noTyped = !attempts(w).some((c) => c.request?.due_on === "2026-11-10" || /10 November/.test(c.request?.body ?? ""));
      const writePorts = ["record_service", "write_job", "record_consent"];
      const noDateWritten = w.calls
        .filter((c) => writePorts.includes(c.port))
        .every((c) => !Object.keys(c.request ?? {}).some((k) => /due/i.test(k)));
      return before && right && noTyped && noDateWritten;
    },
    describe,
  },
  {
    checkId: "warranty-from-the-record",
    world: () =>
      world(
        [
          job("J401", "A-INV-1", "C1", equip({ equipment_type: "solar inverter", make: "Fronius", model: "Primo 5.0", serial: "FR-1001", installed_on: "2021-11-20", warranty_months: 60 })),
          job("J402", "A-INV-2", "C1", equip({ equipment_type: "solar inverter", make: "Fronius", model: "Primo 5.0", serial: "FR-1002", installed_on: "2021-11-20", warranty_months: null })),
        ],
        [customer("C1", "Ana")],
      ),
    drive: (build, w) => run(build, w),
    holds: (w) => {
      const first = sent(w).filter((c) => c.request?.asset_id === "A-INV-1" && c.request?.kind === "warranty");
      const second = attempts(w).filter((c) => c.request?.asset_id === "A-INV-2" && c.request?.kind === "warranty");
      return first.length === 1 && first[0].request.due_on === "2026-11-20" && second.length === 0;
    },
    describe,
  },
  {
    checkId: "reminder-ahead-of-the-date",
    world: () =>
      world(
        [
          job("J501", "A-IN", "C1", equip({ installed_on: "2025-11-20" })),
          job("J502", "A-OUT", "C2", equip({ installed_on: "2026-01-15" })),
          job("J503", "A-PAST", "C3", equip({ installed_on: "2025-10-31" })),
        ],
        [customer("C1", "Ana"), customer("C2", "Ben"), customer("C3", "Cleo")],
      ),
    drive: async (build, w) => {
      await run(build, w);
      await run(build, w);
    },
    holds: (w) => {
      const inside = attempts(w).filter((c) => c.request?.asset_id === "A-IN");
      const one = inside.length === 1 && inside[0].response?.sent === true && inside[0].request.due_on === "2026-11-20";
      const day = one ? TZ_DATE(inside[0].at) : null;
      const inWindow = one && daysBetween(day, "2026-11-20") <= 21 && daysBetween(day, "2026-11-20") >= 0;
      const others = !attempts(w).some((c) => c.request?.asset_id === "A-OUT" || c.request?.asset_id === "A-PAST");
      return one && inWindow && others;
    },
    describe,
  },
  {
    checkId: "channel-they-agreed-to",
    world: () =>
      world(
        [job("J601", "A-EMAIL", "C-EM", equip()), job("J602", "A-NONE", "C-NO", equip())],
        [customer("C-EM", "Ana", { email: true }), customer("C-NO", "Ben", {})],
      ),
    drive: (build, w) => run(build, w),
    holds: (w) => {
      const em = attempts(w).filter((c) => c.request?.customer_id === "C-EM");
      const emailOnly = em.length >= 1 && em.every((c) => c.request.channel === "email" && c.response?.sent === true);
      const none = !attempts(w).some((c) => c.request?.customer_id === "C-NO");
      return emailOnly && none && raisedKind(w, "no_consent", "A-NONE");
    },
    describe,
  },
  {
    checkId: "already-booked-no-reminder",
    world: () =>
      world(
        [
          job("J701", "A-AC-7", "C1", equip({ equipment_type: "split system air conditioner", make: "Daikin", model: "FTXM35" })),
          job("J702", "A-AC-7", "C1", null, "service", "scheduled"),
          job("J703", "A-HWS-7", "C2", equip()),
        ],
        [customer("C1", "Ana"), customer("C2", "Ben")],
      ),
    drive: (build, w) => run(build, w),
    holds: (w) => {
      const none = !attempts(w).some((c) => c.request?.asset_id === "A-AC-7");
      const all = attempts(w);
      const preceded = all.every((s) => {
        const idx = w.calls.indexOf(s);
        return w.calls
          .slice(0, idx)
          .some((c) => c.port === "read_job" && c.request?.asset_id === s.request.asset_id && c.request?.open === true && c.response);
      });
      return none && all.length >= 1 && preceded;
    },
    describe,
  },
  {
    checkId: "one-follow-up-then-stop",
    world: () =>
      world(
        [job("J801", "A-QUIET", "C1", equip({ installed_on: "2025-11-25" })), job("J802", "A-ASKS", "C2", equip({ installed_on: "2025-11-25" }))],
        [customer("C1", "Ana"), customer("C2", "Ben")],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.reply({ customer_id: "C2", asset_id: "A-ASKS", kind: "service", due_on: "2026-11-25", channel: "sms", text: "Can you come after 3pm on a weekday?" });
      w.advanceDays(8);
      await run(build, w);
      w.advanceDays(8);
      await run(build, w);
      w.advanceDays(21);
      await run(build, w);
    },
    holds: (w) => {
      const s = sent(w);
      const key = (c) => `${c.request.asset_id}|${c.request.kind}|${c.request.due_on}`;
      const keys = [...new Set(s.map(key))];
      const capped = keys.every(
        (k) => s.filter((c) => key(c) === k && c.request.stage === "reminder").length <= 1 && s.filter((c) => key(c) === k && c.request.stage === "follow_up").length <= 1,
      );
      const gapOk = s
        .filter((c) => c.request.stage === "follow_up")
        .every((f) => {
          const r = s.find((c) => key(c) === key(f) && c.request.stage === "reminder");
          return !!r && daysBetween(TZ_DATE(r.at), TZ_DATE(f.at)) >= 7;
        });
      const quietOne = s.filter((c) => c.request.asset_id === "A-QUIET" && c.request.stage === "follow_up").length === 1;
      const askerNone = !attempts(w).some((c) => c.request?.asset_id === "A-ASKS" && c.request?.stage === "follow_up");
      const unclear = of(w, "escalate").some((c) => c.request?.kind === "unclear_reply" && String(c.request?.detail ?? "").startsWith("A-ASKS;"));
      return capped && gapOk && quietOne && askerNone && unclear;
    },
    describe,
  },
  {
    checkId: "opt-out-for-good",
    world: () => world([job("J901", "A-HWS-9", "C-S", equip())], [customer("C-S", "Ana"), customer("C-O", "Ben")]),
    drive: async (build, w) => {
      await run(build, w);
      w.reply({ customer_id: "C-S", asset_id: "A-HWS-9", kind: "service", due_on: "2026-11-20", channel: "sms", text: "STOP" });
      await run(build, w);
      w.addJob(job("J902", "A-AC-9", "C-S", equip({ equipment_type: "split system air conditioner", make: "Daikin", model: "FTXM35", installed_on: "2025-11-22" })));
      await run(build, w);
      w.advanceDays(8);
      await run(build, w);
    },
    holds: (w) => {
      const stopIdx = w.calls.findIndex(
        (c) => c.port === "record_consent" && c.request?.customer_id === "C-S" && c.request?.withdrawn === true && c.response?.ok === true,
      );
      if (stopIdx < 0) return false;
      const before = w.calls.slice(0, stopIdx).some((c) => c.port === "send_message" && c.request?.customer_id === "C-S");
      const after = w.calls.slice(stopIdx).some((c) => c.port === "send_message" && c.request?.customer_id === "C-S");
      const newCaptured = of(w, "record_service").some((c) => c.request?.source_job_id === "J902" && c.response?.record_id);
      return before && !after && newCaptured;
    },
    describe,
  },
  {
    checkId: "warranty-says-only-the-date",
    world: () =>
      world(
        [job("J1001", "A-INV-10", "C1", equip({ equipment_type: "solar inverter", make: "Fronius", model: "Primo 5.0", installed_on: "2021-11-20", warranty_months: 60 }))],
        [customer("C1", "Ana")],
      ),
    drive: (build, w) => run(build, w),
    holds: (w) => {
      const wr = sent(w).filter((c) => c.request?.kind === "warranty");
      const dated = wr.length === 1 && wr[0].request.due_on === "2026-11-20" && /\b20 November 2026\b/.test(wr[0].request.body ?? "");
      const clean = attempts(w).every((c) => !/cover|free|repair|claim|guarantee|consumer|rights|entitle/i.test(c.request?.body ?? ""));
      return dated && clean;
    },
    describe: (w) => `${describe(w)}; bodies: ${attempts(w).map((c) => JSON.stringify(c.request?.body)).join(" | ")}`,
  },
  {
    checkId: "one-booking-request",
    world: () =>
      world(
        [job("J1101", "A-YES", "C-A", equip()), job("J1102", "A-LINK", "C-B", equip({ installed_on: "2025-11-22" }))],
        [customer("C-A", "Ana"), customer("C-B", "Ben", { email: true })],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.reply({ customer_id: "C-A", asset_id: "A-YES", kind: "service", due_on: "2026-11-20", channel: "sms", text: "YES" });
      w.reply({ customer_id: "C-B", asset_id: "A-LINK", kind: "service", due_on: "2026-11-22", channel: "link", text: "booking link tapped" });
      await run(build, w);
      w.reply({ customer_id: "C-A", asset_id: "A-YES", kind: "service", due_on: "2026-11-20", channel: "sms", text: "Yes" });
      await run(build, w);
      await run(build, w);
    },
    holds: (w) => {
      const ws = writes(w);
      const a = ws.filter((c) => c.request?.asset_id === "A-YES");
      const b = ws.filter((c) => c.request?.asset_id === "A-LINK");
      return ws.length === 2 && a.length === 1 && a[0].request.customer_id === "C-A" && b.length === 1 && b[0].request.customer_id === "C-B";
    },
    describe,
  },
  {
    checkId: "no-time-no-price",
    world: () =>
      world(
        [job("J1201", "A-Y1", "C-A", equip()), job("J1202", "A-Y2", "C-B", equip({ installed_on: "2025-11-21" }))],
        [customer("C-A", "Ana"), customer("C-B", "Ben")],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.advanceDays(1);
      w.reply({ customer_id: "C-A", asset_id: "A-Y1", kind: "service", due_on: "2026-11-20", channel: "sms", text: "Yes please" });
      await run(build, w);
      w.advanceDays(2);
      w.reply({ customer_id: "C-B", asset_id: "A-Y2", kind: "service", due_on: "2026-11-21", channel: "sms", text: "yes" });
      await run(build, w);
    },
    holds: (w) => {
      const ws = writes(w);
      const BAD_KEY = /time|slot|start|end|price|amount|cost|rate|scheduled|appointment/i;
      const BAD_VAL = /\$\s?\d|\b\d{1,2}:\d{2}\b|\b\d{1,2}\s?(am|pm)\b/i;
      const clean = ws.every((c) =>
        Object.entries(c.request ?? {}).every(([k, v]) => !BAD_KEY.test(k) && !(typeof v === "string" && k !== "reply_text" && BAD_VAL.test(v))),
      );
      const told = ws.every((c) => of(w, "notify").some((n) => n.request?.job_id === c.response.job_id && /book/i.test(n.request?.reason ?? "")));
      return ws.length === 2 && clean && told;
    },
    describe,
  },
  {
    checkId: "record-by-asset",
    world: () =>
      world(
        [
          job("J1301", "A-R1", "C-A", equip()),
          job("J1302", "A-R2", "C-B", equip({ installed_on: "2025-11-21" })),
          job("J1303", "A-R3", "C-C", equip({ installed_on: "2025-11-24" })),
        ],
        [customer("C-A", "Ana"), customer("C-B", "Ben", { email: true }), customer("C-C", "Cleo")],
      ),
    drive: async (build, w) => {
      await run(build, w);
      w.reply({ customer_id: "C-A", asset_id: "A-R1", kind: "service", due_on: "2026-11-20", channel: "sms", text: "Yes " });
      w.reply({ customer_id: "C-B", asset_id: "A-R2", kind: "service", due_on: "2026-11-21", channel: "email", text: "Please stop emailing me." });
      w.advanceDays(8);
      await run(build, w);
    },
    holds: (w) => {
      const ev = of(w, "evidence").filter((c) => c.response?.entry_id).map((c) => c.request);
      const sends = sent(w);
      const sendsLogged = sends.every((s) =>
        ev.some((e) => e.message_id === s.response.message_id && e.asset_id === s.request.asset_id && e.entry === s.request.stage && e.channel === s.request.channel),
      );
      const followed = sends.some((s) => s.request.stage === "follow_up" && s.request.asset_id === "A-R3");
      const repliesLogged = w.inbox.every((r) => ev.some((e) => e.entry === "reply" && e.reply_id === r.reply_id && e.asset_id === r.asset_id && e.text === r.text));
      const stopLogged = ev.some((e) => e.entry === "stop" && e.asset_id === "A-R2");
      const ws = writes(w);
      const bookingLogged = ws.length === 1 && ev.some((e) => e.entry === "booking_request" && e.asset_id === "A-R1" && e.job_id === ws[0].response.job_id);
      return sends.length >= 4 && sendsLogged && followed && repliesLogged && stopLogged && bookingLogged;
    },
    describe,
  },
  {
    checkId: "survives-the-builder",
    // A precondition. The runner reports it as evidence_required and never
    // runs this world; the owner names who else can explain the build and
    // whose account the schedule, the reminders and the record run on.
    world: () => world([], []),
    drive: () => {},
    holds: () => false,
    describe: () => "not a software check",
  },
];

// The pass test runs only in the business's own job system, with a real
// phone. On the stub the runner reports it with_us. It is quoted as a scoped
// build on the job system the business already runs.
export const liveScenarios = [
  {
    checkId: "pass-test",
    world: () => world([], []),
    drive: () => {},
    holds: () => false,
    describe: () => "live only",
  },
];
